fn test_a_match_at_distance_32768_is_used() {
    // Ten rare bytes, 32,758 bytes that never contain byte 1, the ten again:
    // the only way to code the last ten cheaply is distance 32,768. Against
    // the same data with the last byte changed, the stream is shorter.
    let src: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ws: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let z: &mut crate::port::Buf = &mut crate::port::Buf::new();
    let dec: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let st: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let rnd: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let mut i: i32 = 0;
    let mut zn1: i32 = 0;
    sm_seed(rnd, 21);
    while i < 10 {
        crate::port::cells_push(src, 1 + i);
        i += 1;
    }
    while i < 32768 {
        crate::port::cells_push(src, 20 + sm_below(rnd, 200));
        i += 1;
    }
    i = 0;
    while i < 10 {
        crate::port::cells_push(src, 1 + i);
        i += 1;
    }
    crate::testport::assert_eq(crate::port::cells_len(src), 32778, "length");
    zn1 = dt_compress(ws, z, src, 32778, 2);
    crate::testport::assert_eq(dt_verify(z, src, 32778, dec, st), -1, "round trip");
    crate::port::cells_set(src, 32777, 99);
    let zn2: i32 = dt_compress(ws, z, src, 32778, 2);
    crate::testport::assert_that((zn2 - zn1) > 0, "a changed last byte costs more bytes");
    crate::testport::assert_eq(dt_verify(z, src, 32778, dec, st), -1, "round trip, changed");
}
