#[test]
fn test_the_output_does_not_depend_on_how_the_input_is_split() {
    let src: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ws: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let whole: &mut crate::port::Buf = &mut crate::port::Buf::new();
    let bytewise: &mut crate::port::Buf = &mut crate::port::Buf::new();
    let chunks: &mut crate::port::Buf = &mut crate::port::Buf::new();
    let mut i: i32 = 0;
    dt_fill_text(src, 70000, 13);
    dt_compress(ws, whole, src, 70000, 0);
    df_init(ws);
    while i < 70000 {
        df_write_cells(ws, bytewise, src, i, i + 1);
        i += 1;
    }
    df_finish(ws, bytewise);
    df_init(ws);
    i = 0;
    while i < 70000 {
        df_write_cells(ws, chunks, src, i, i + 1000);
        i += 1000;
    }
    df_finish(ws, chunks);
    crate::testport::assert_eq(dt_same(whole, bytewise), 1, "byte by byte");
    crate::testport::assert_eq(dt_same(whole, chunks), 1, "in chunks of 1000");
}
